// A clean, mobile-friendly page for approvers, suppliers, contractors and the certifier.
const page = (title, body, opts = {}) => {
  const cfg = configFrom();
  return `<!doctype html><html lang="en-NZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title>${FONT_LINK}<style>${THEME}</style></head><body>
<header class="top"><b>${BRAND_MARK}${esc(cfg.business_name || 'Tussock Ridge Farming Ltd')}</b><span>${esc(opts.tag || 'Secure link')}</span></header>
<main class="card${opts.wide ? ' wide' : ''}">${body}</main>
<div class="foot">Demo by Forrof. All people, businesses and numbers are fictional.</div></body></html>`;
};

// Farm plan evidence: item states, pack status and the draft evidence pack page. Injected into the nodes that use them.
const EVIDENCE_PILL = { missing: ['bad', 'Missing'], requested: ['warn', 'Requested'], received: ['info', 'Check needed'], verified: ['ok', 'Verified'] };
const evidencePill = (item) => { const [tone, label] = EVIDENCE_PILL[item.status] || ['grey', item.status]; return pill(tone, label); };
const PACK_PILL = { Collecting: ['warn', 'Collecting evidence'], 'Ready for sign-off': ['info', 'Ready for sign-off'], 'Sent to certifier': ['ok', 'Sent to certifier'] };
const packPill = (farm) => { const [tone, label] = PACK_PILL[farm.pack_status] || ['grey', farm.pack_status]; return pill(tone, label); };

const farmItems = (farm, items) => items.filter((i) => i.farm_id === farm.farm_id);
const evidenceCounts = (items) => ({
  total: items.length,
  verified: items.filter((i) => i.status === 'verified').length,
  received: items.filter((i) => i.status === 'received').length,
  requested: items.filter((i) => i.status === 'requested').length,
  missing: items.filter((i) => i.status === 'missing').length,
});
// A pack is ready once every item is verified. A pack that has been signed off and sent stays sent until the rules change.
const packStatusFor = (farm, items) => {
  if (farm.pack_status === 'Sent to certifier') return 'Sent to certifier';
  return items.length && items.every((i) => i.status === 'verified') ? 'Ready for sign-off' : 'Collecting';
};
const deadlineText = (cfg, today) => {
  if (!cfg.plan_deadline) return '';
  const n = daysBetween(today, cfg.plan_deadline);
  return `${fmtDate(cfg.plan_deadline)} (${n >= 0 ? `${n} days to go` : `${-n} days ago`})`;
};
// Whose phone or email an evidence request goes to: the named provider, or the farm's own manager.
const providerFor = (req, farm) => (req.provider_name
  ? { name: req.provider_name, email: req.provider_email || '', phone: req.provider_phone || '' }
  : { name: farm.manager_name, email: farm.manager_email, phone: farm.manager_phone });

// The pack: what the certifier receives after a person signs it off. Built only from records a person has verified.
const packBody = (farm, items, cfg, events) => {
  const mine = farmItems(farm, items);
  const c = evidenceCounts(mine);
  const today = nzToday();
  const outstanding = mine.filter((i) => i.status !== 'verified');
  const rows = mine.map((i) => `<tr><td>${esc(i.requirement)}<div class="muted">${esc(i.category)}</div></td><td>${esc(i.provider_name || farm.manager_name)}</td>
    <td>${i.file_name ? `<a href="${cfg.base_url}/webhook/farmplan/file?p=${farm.pack_token}&amp;id=${esc(i.item_id)}" target="_blank">${esc(i.original_name || i.file_name)}</a>` : '<span class="muted">No file</span>'}</td>
    <td>${evidencePill(i)}${i.verified_at ? `<div class="muted">${esc(i.verified_by)}, ${fmtDate(i.verified_at)}</div>` : ''}</td></tr>`).join('');
  const status = farm.pack_status === 'Sent to certifier'
    ? callout('ok', `<b>Signed off and sent.</b> ${esc(farm.signed_by)} signed this pack off on ${fmtLong(String(farm.signed_at).slice(0, 10))} and it was sent to ${esc(farm.sent_to)}.`)
    : farm.pack_status === 'Ready for sign-off'
      ? callout('info', `<b>Ready for sign-off.</b> All ${c.total} items are verified. Nothing is sent to the certifier until a person signs this off.`)
      : callout('warn', `<b>Not ready.</b> ${c.total - c.verified} of ${c.total} items are still outstanding.`);
  const history = (events || []).slice(-14).map((e) => `<tr><td class="muted">${fmtTime(e.at)}</td><td>${esc(e.actor)}</td><td>${esc(e.action)}</td></tr>`).join('');
  return `<div class="sheet">
<h1>Evidence pack for ${esc(farm.name)}</h1>
<p class="muted">Draft prepared by the farm admin agent from records a person has verified. It is not the freshwater farm plan itself: the plan is prepared in the format your certifier and regional council require.</p>
${status}
<table class="kv">
<tr><td>Farm</td><td>${esc(farm.name)}, ${esc(farm.farm_type)}, ${esc(farm.location)}, ${esc(farm.region)}</td></tr>
<tr><td>Area</td><td>${Number(farm.area_ha).toLocaleString('en-NZ')} ha</td></tr>
<tr><td>Farm manager</td><td>${esc(farm.manager_name)}</td></tr>
<tr><td>Certifier</td><td>${esc(cfg.certifier_name)}</td></tr>
<tr><td>Due date for certified plans</td><td>${esc(deadlineText(cfg, today))}</td></tr>
<tr><td>Evidence verified</td><td>${c.verified} of ${c.total}</td></tr>
</table>
<h2>Evidence index</h2>
<table class="list"><tr><th>Evidence</th><th>Supplied by</th><th>File</th><th>Status</th></tr>${rows}</table>
${outstanding.length ? `<h2>Still outstanding</h2><ul>${outstanding.map((i) => `<li>${esc(i.requirement)} (${esc(i.status)})</li>`).join('')}</ul>` : ''}
<h2>What happened</h2>
<table class="list"><tr><th>When</th><th>Who</th><th>What</th></tr>${history || '<tr><td colspan="3" class="muted">No events yet.</td></tr>'}</table>
<p class="muted">The checklist is an example set by ${esc(cfg.business_name)}. Confirm with your certifier what a plan needs.</p>
</div>`;
};

// POST /webhook/farmplan/signoff: the owner signs the pack off. Only then is anything sent to the certifier.
// Returns { farmUpdates, messages, audit, html }.
const cfg = configFrom();
const body = $('Owner signs off').first().json.body || {};
const token = String(body.t || '');
const farm = tableRows('Farms').find((f) => token && f.signoff_token === token);
const none = { farmUpdates: [], messages: [], audit: [] };
if (!farm) return [{ json: { ...none, html: page('Link not found', `<h1>This link is no longer valid</h1><p class="muted">Ask ${esc(cfg.admin_name)} for a new one.</p>`) } }];
const again = (error) => {
  const events = tableRows('Audit log').filter((a) => a.flow === 'Farm plan' && a.subject === farm.name).sort((a, b) => String(a.at).localeCompare(String(b.at)));
  return [{ json: { ...none, html: page(`Sign off: ${farm.name}`, `${callout('bad', esc(error))}${packBody(farm, tableRows('Evidence'), cfg, events)}<p><a class="btn line" href="${cfg.base_url}/webhook/farmplan/signoff?t=${esc(token)}">Back to the sign-off form</a></p>`, { wide: true, tag: 'Sign-off' }) } }];
};
if (farm.pack_status !== 'Ready for sign-off') {
  return [{ json: { ...none, html: page('Nothing to sign', `<h1>Nothing to sign off</h1>${callout('info', farm.pack_status === 'Sent to certifier' ? `This pack was already signed off by ${esc(farm.signed_by)} and sent to ${esc(farm.sent_to)}.` : 'This pack is not ready: some evidence is still outstanding.')}`) } }];
}
const name = String(body.name || '').trim();
if (body.confirm !== 'yes') return again('Tick the box to confirm you have read the pack.');
if (name.toLowerCase() !== String(cfg.owner_name).toLowerCase()) return again(`Only ${cfg.owner_name} can sign this off. Type the full name exactly.`);

const now = nowIso();
const items = farmItems(farm, tableRows('Evidence'));
const link = `${cfg.base_url}/webhook/farmplan/pack?t=${farm.pack_token}`;
const manager = { name: farm.manager_name, email: farm.manager_email };
return [{ json: {
  farmUpdates: [{ id: farm.id, pack_status: 'Sent to certifier', signed_by: cfg.owner_name, signed_at: now, sent_at: now, sent_to: cfg.certifier_name }],
  messages: [
    msg({ channel: 'Email', to_name: cfg.certifier_name, to_address: cfg.certifier_email, link, related: farm.farm_id, workflow: 'Pack sent to certifier',
      subject: `Evidence pack for ${farm.name}, signed off by ${cfg.owner_name}`,
      body: `Kia ora ${firstName(cfg.certifier_name)},\n\n${cfg.owner_name} has signed off the evidence pack for ${farm.name} (${farm.farm_type}, ${farm.location}). All ${items.length} items are verified and each links to its file.\n\nQuestions go to ${cfg.admin_name} at ${cfg.admin_email}. This message is automated, and was sent only after ${cfg.owner_name} signed.` }),
    msg({ channel: 'Email', to_name: manager.name, to_address: manager.email, link, related: farm.farm_id, workflow: 'Pack sent to certifier',
      subject: `${farm.name} evidence pack signed off and sent`,
      body: `Kia ora ${firstName(manager.name)}, ${cfg.owner_name} signed off the ${farm.name} evidence pack and it has gone to ${cfg.certifier_name}.` }),
  ],
  audit: [
    auditRow(cfg.owner_name, 'person', 'Farm plan', farm.name, 'Signed off the evidence pack', `${items.length} items, all verified. Signed by typing the full name.`),
    auditRow('Agent', 'agent', 'Farm plan', farm.name, `Sent the pack to ${cfg.certifier_name}`, `Emailed ${cfg.certifier_email} with a link to the pack, after ${cfg.owner_name} signed.`),
  ],
  html: page('Signed off', `<h1>Signed off</h1>${callout('ok', `<b>The ${esc(farm.name)} pack has gone to ${esc(cfg.certifier_name)}.</b> It is recorded with your name and the time.`)}<p><a class="btn line" href="${link}">View the pack</a></p>`),
} }];

// Shared helpers injected at the top of every Code node by scripts/build-workflows.mjs.
const TZ = 'Pacific/Auckland';
const DAY_MS = 86400000;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const round2 = (n) => Math.round(Number((Number(n || 0) * 100).toFixed(6))) / 100;
const money = (n) => new Intl.NumberFormat('en-NZ', { style: 'currency', currency: 'NZD' }).format(Number(n || 0));
const priceText = (n) => '$' + Number(n || 0).toLocaleString('en-NZ', { minimumFractionDigits: 2, maximumFractionDigits: 4 });
const qtyText = (n) => Number(n || 0).toLocaleString('en-NZ', { maximumFractionDigits: 2 });
const unitText = (qty, unit) => (Number(qty) !== 1 && { load: 'loads', bale: 'bales' }[unit]) || unit;
const newToken = () => require('crypto').randomBytes(18).toString('hex');
// Each call is one millisecond later than the last, so rows written in one run keep their order.
let _seq = 0;
const nowIso = () => new Date(Date.now() + _seq++).toISOString();

// Calendar dates are plain "YYYY-MM-DD" strings in New Zealand time, so this PC's own clock never matters.
const nzToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const dateOf = (s) => new Date(`${String(s).slice(0, 10)}T00:00:00Z`);
const isoDay = (d) => d.toISOString().slice(0, 10);
const addDays = (s, n) => isoDay(new Date(dateOf(s).getTime() + n * DAY_MS));
const addMonths = (s, n) => {
  const d = dateOf(s);
  const day = d.getUTCDate();
  const target = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + n, 1));
  const last = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0)).getUTCDate();
  target.setUTCDate(Math.min(day, last));
  return isoDay(target);
};
const daysBetween = (from, to) => Math.round((dateOf(to) - dateOf(from)) / DAY_MS);
const fmtDate = (s) => (s ? dateOf(s).toLocaleDateString('en-NZ', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' }) : '—');
const fmtLong = (s) => (s ? dateOf(s).toLocaleDateString('en-NZ', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : '—');
const fmtTime = (iso) => (iso ? new Date(iso).toLocaleString('en-NZ', { timeZone: TZ, day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit', hour12: true }) : '');
const ago = (iso) => {
  if (!iso) return '';
  const s = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
  if (s < 60) return 'just now';
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  return `${Math.round(s / 86400)} d ago`;
};

// Every Code node runs right after "Load data", whose single item holds one array per data table.
const DATA = $input.first().json || {};
const tableRows = (table) => (Array.isArray(DATA[table]) ? DATA[table] : []);
const configFrom = () => Object.fromEntries(tableRows('Config').map((r) => [r.key, r.value]));
const firstName = (name) => String(name || '').split(' ')[0];
const person = (cfg, role) => ({ name: cfg[`${role}_name`] || '', email: cfg[`${role}_email`] || '', phone: cfg[`${role}_phone`] || '' });

// A message for the Shared · Send message workflow. Nothing is sent from anywhere else.
const msg = (m) => ({
  channel: m.channel, to_name: m.to_name || '', to_address: m.to_address || '', subject: m.subject || '',
  body: m.body || '', link: m.link || '', related: m.related || '', workflow: m.workflow || '',
});
// Text the phone if we have one, otherwise email. `both` sends the email as well.
const reach = (p, m, how = 'auto') => {
